ALTER TABLE public.transactions ADD COLUMN classification text NOT NULL DEFAULT 'regular', ADD COLUMN flag text, ADD COLUMN flag_note text; ALTER TABLE public.recurring_bills ADD COLUMN kind text NOT NULL DEFAULT 'expense'; CREATE TABLE public.merchant_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, merchant_key text NOT NULL, category_id uuid REFERENCES public.categories(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (user_id, merchant_key)); GRANT SELECT, INSERT, UPDATE, DELETE ON public.merchant_rules TO authenticated; GRANT ALL ON public.merchant_rules TO service_role; ALTER TABLE public.merchant_rules ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users read own merchant rules" ON public.merchant_rules FOR SELECT TO authenticated USING (user_id = auth.uid()); CREATE POLICY "Users insert own merchant rules" ON public.merchant_rules FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid()); CREATE POLICY "Users update own merchant rules" ON public.merchant_rules FOR UPDATE TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid()); CREATE POLICY "Users delete own merchant rules" ON public.merchant_rules FOR DELETE TO authenticated USING (user_id = auth.uid()); CREATE INDEX merchant_rules_user_idx ON public.merchant_rules(user_id, merchant_key); COMMENT ON COLUMN public.transactions.classification IS 'regular = normal income/expense; transfer = between the user''s own accounts; refund; loan; credit_card_payment. Non-regular classes are excluded from income/expense totals.'; COMMENT ON COLUMN public.transactions.flag IS 'review flag: duplicate | unusual | ambiguous | uncategorized; set by detection logic or the user'; COMMENT ON COLUMN public.recurring_bills.kind IS 'expense (default) or income; income bills feed recurring-income detection';